/// <summary>
/// Logic block needed to post inventory journals from the device
/// </summary>
public class MwmsLogicBlockPostInventoryJournal extends MwmsLogicBlock implements TFMLogicBlockPostAdhocRegistrationInterface, TFMTranslationDeclarantInterface
{
    str postJournalId = 'PostJournal';

}

Method.Source:
public Set autoCreatedProcesses()
{
    Set ret = super();

    TFMProcess process = TFMProcess::Construct(postJournalId);

    process.addBlock(this);
    ret.add(process);

    return ret;
}

public Map addTranslations()
{
    Map translations = new Map(Types::String, Types::String);
    translations.add(postJournalId, TFMTranslationProvider::getTFDeviceLabelValue(postJournalId, null));
    return translations;
}

public static MwmsLogicBlockPostInventoryJournal Construct()
{
    return new MwmsLogicBlockPostInventoryJournal();
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A MobPostResponseData object.</returns>
public TFMPostResponseData post()
{
    InventJournalTable  inventJournal;
    Common              refTable = request.getReferredRecord();
    TFMPostResponseData postResponse= TFMPostResponseData::Construct();

    if (!refTable)
    {
        refTable = request.logicContext().getTableFromAnyBlock(tableStr(InventJournalTable));
    }
    if (!refTable && InventJournalTable::exist(request.getFieldValue(extendedTypeStr(JournalId))))
    {
        refTable = InventJournalTable::find(request.getFieldValue(extendedTypeStr(JournalId)));
    }

    if (refTable.TableId != tableNum(InventJournalTable))
    {
        throw Error ("@TaskletMobileWMS:ThisfunctiononlyworkswithInvento");
    }

    inventJournal = refTable;

    ttsbegin;
    inventJournal.selectForUpdate(true);

    MobPostHelper::postInventJournalTransfer(inventJournal);
    ttscommit;
    postResponse.parmResponseText(strFmt("@TaskletMobileWMS:Journal1postedsuccessfully", inventJournal.JournalId));
    return postResponse;
}
